import boto3

def moderate_transcript(text):
    comprehend = boto3.client('comprehend')
    response = comprehend.detect_sentiment(Text=text, LanguageCode='en')
    sentiment = response['Sentiment']
    if sentiment == 'NEGATIVE':
        return 'Moderation required: Negative sentiment detected.'
    else:
        return 'Transcript approved.'

from google.cloud import speech_v1p1beta1 as speech

def create_batch_request(audio_uri, output_uri):
    config = speech.RecognitionConfig(
        encoding=speech.RecognitionConfig.AudioEncoding.LINEAR16,
        sample_rate_hertz=16000,
        language_code='en-US',
    )
    audio = speech.RecognitionAudio(uri=audio_uri)
    request = speech.BatchRecognizeRequest(
        config=config,
        audio=audio,
        output_uri=output_uri,
    )
    return request

def handle_batch_response(response):
    if response.results:
        for result in response.results:
            if result.alternatives:
                transcript = result.alternatives[0].transcript
                print(f'Transcript: {transcript}')
            else:
                print('No alternatives found.')
    else:
        print('No results found.')

def normalize_transcript(transcript):
    normalized = transcript.lower().strip()
    return normalized

import boto3

def poll_transcription_job(job_name):
    transcribe = boto3.client('transcribe')
    while True:
        response = transcribe.get_transcription_job(TranscriptionJobName=job_name)
        job_status = response['TranscriptionJob']['TranscriptionJobStatus']
        if job_status in ['COMPLETED', 'FAILED']:
            break
    return response

def get_transcript(job_name):
    response = poll_transcription_job(job_name)
    if response['TranscriptionJob']['TranscriptionJobStatus'] == 'COMPLETED':
        transcript_uri = response['TranscriptionJob']['Transcript']['TranscriptFileUri']
        return transcript_uri
    else:
        return 'Transcription job failed'

